  // Help page
  "help.eyebrow": "مركز المساعدة",
  "help.title": "كيف يمكننا المساعدة؟",
  "help.subtitle": "أدلة TYRO والأسئلة الشائعة وجهات الدعم.",
  "help.sections.support": "جهات الدعم",
  "help.sections.supportSubtitle": "تواصل معنا إذا لم تجد ما تبحث عنه",
  "help.faq.q1": "لماذا يظهر أحد المساعدين مقفلًا؟",
  "help.faq.a1":
    "يُفتح المساعدون ومنتجات الذكاء الاصطناعي وفق قائمة التطبيقات التي حدّدها المسؤول لك؛ وإن لم يكن أحدها في قائمتك فيظهر مقفلًا. اضغط «اطلب الوصول» على بطاقته في الصفحة الرئيسية واكتب السبب؛ وتتابع الحالة في ملفي ← الوصول.",
  "help.faq.q2": "لا أرى قسم الكتالوج في ملفي.",
  "help.faq.a2":
    "تحرير الكتالوج (المساعدون ومنتجات الذكاء الاصطناعي وتطبيقات الأعمال) متاح لمجموعة المسؤولين. يمكنك رؤية حالتك في ملفي ← الوصول.",
  "help.faq.q3": "أين تُحفظ التعريفات وتفضيلاتي؟",
  "help.faq.a3":
    "كتالوج المساعدين والتطبيقات محفوظ في Dataverse — القائمة واحدة للجميع. أما الوضع والسمة واللغة والمفضلة فتُحفظ في هذا المتصفح فقط (localStorage)، وتجد قائمتها في ملفي ← هذا المتصفح. محتوى البريد والتقويم والملفات يبقى في الذاكرة فقط ويُمحى عند الخروج.",
  "help.faq.q4": "التقويم أو البريد أو الملفات تقول إن الوصول غير معتمد.",
  "help.faq.a4":
    "تعمل اللوحات بأذونات Microsoft Graph. بمجرد اعتماد الإذن في المستأجر تُفتح اللوحة دون أي تغيير في الكود — يكفي أن تطلب من مسؤول تقنية المعلومات الإذن الذي تذكره اللوحة (مثل Mail.Read). صور الأشخاص تحتاج إذنًا منفصلًا؛ بدونه تظهر الأحرف الأولى.",
  "help.faq.q5": "هل توجد اختصارات لوحة مفاتيح؟",
  "help.faq.a5":
    "Ctrl/⌘+K يفتح البحث: الأشخاص والمكاتب والصفحات والملفات والإجراءات السريعة. في المحادثة Enter يرسل، وShift+Enter يضيف سطرًا جديدًا، وEsc يغلق اللوحة الجانبية.",
  "help.faq.q6": "كيف أضيف إلى المفضلة وأين تُحفظ؟",
  "help.faq.a6":
    "اضغط القلب الذي يظهر على البطاقة، أو السطر الثاني في قائمة التطبيق بالشريط الجانبي. القائمة تُكتب في هذا المتصفح؛ التطبيق الذي يتغير اسمه يظهر باسمه الجديد، والذي يُحذف من الكتالوج لا يُعرض — لكن المفضلة لا تُمسح.",
  "help.faq.q7": "هل يمكنني تثبيت التطبيق على هاتفي؟",
  "help.faq.a7":
    "نعم. اضغط «تثبيت TYRO» في قائمة المستخدم (أو زر التثبيت أدناه)؛ يفتح التطبيق في نافذته الخاصة، وعلى الهاتف من الشاشة الرئيسية. على iPhone وiPad يعرض البند نفسه دليل Safari بخطوتين.",
  "help.faq.q8": "ما لغات الواجهة المتاحة؟",
  "help.faq.a8": "التركية والإنجليزية والروسية والعربية.",
  "help.support.email.title": "راسلنا بالبريد",
  "help.support.teams.title": "راسلنا على Teams",
  "help.search.placeholder": "ابحث في الأدلة والإجابات",
  "help.search.aria": "ابحث في صفحة المساعدة",
  "help.search.empty": "هذه الكلمة لا ترد في هذه الصفحة.",
  "help.search.emptyHint":
    "جرّب كلمة أخرى أو راسل جهات الدعم أدناه — إن لم تكن الإجابة هنا فهذا يعني أنها تحتاج إلى إضافة.",
  "help.search.hint": "يبحث في الأدلة والأسئلة الشائعة. الاختصار: /",
  "help.search.clear": "مسح البحث",
  "help.popular": "شائع",
  "help.popular.1": "اختصار",
  "help.popular.2": "مساعد مقفل",
  "help.popular.3": "إشعارات",
  "help.popular.4": "مفضلة",
  "help.popular.5": "إذن",
  "help.faq.q9": "كيف أعرف أن الرد جاهز؟",
  "help.faq.a9":
    "امنح إذن إشعارات المتصفح من ملفي؛ سنُعلمك بجاهزية الرد حتى لو كان التبويب في الخلفية. وفي المكان نفسه زر إشعار تجريبي — فإن لم يظهر شيء فالخلل في إعدادات إشعارات نظام التشغيل لا في المتصفح. وبدون الإذن نُعلمك عبر عنوان التبويب والشارة.",
  "help.nav.aria": "أقسام المساعدة",
  "help.nav.shortcuts": "الاختصارات",
  "help.nav.support": "الدعم",
  "help.faq.q10": "كيف أفتح طلب إجازة أو مصروف أو سلفة عمل؟",
  "help.faq.a10":
    "في الخدمة الذاتية اضغط «جديد» (على الهاتف علامة + أسفل الشاشة) واختر النوع، أو اكتبه جملةً عبر «صِف». ينشئ TYRO الطلب في نظام ERP وتتابع حالته في قائمة الخدمة الذاتية.",
  "help.faq.q11": "كيف أضيف إيصال مصروف؟",
  "help.faq.a11":
    "في نموذج المصروف اضغط «أضف إيصالًا»، أو «التقط صورة» على الهاتف، أو اسحب الصورة. يمكنك أيضًا لصق البنود من Excel. وقبل الإرسال تعرض صفحة «مراجعة» كل شيء مرة أخرى.",
  "help.faq.q12": "ماذا يفهم «صِف»؟",
  "help.faq.a12":
    "التواريخ («yarın» و«cuma» و«aralık ilk hafta»)، ونوع الإجازة، وبنود المصروف («Opet 2000 benzin»)، والغرض من السلفة. يعرض ما فهمه في النموذج، ولا يُرسل شيء قبل أن ترسله أنت. يظهر «صِف» فقط عندما تكون لغة الواجهة التركية، ولا يفهم إلا الجمل التركية.",
  "help.faq.q13": "ماذا أرى في «استكشاف»؟",
  "help.faq.a13":
    "إشعارات عملك الخاصة بك في موجز واحد. في «بحث» تبحث عن الأشخاص والمكاتب وأحدث ملفاتك ومرفقات بريدك؛ اضغط على المرفق لمعاينته. ويمكنك الإعجاب بمنشور أو مشاركته أو حفظه.",
  "help.faq.q14": "هل To-Do هو نفسه Microsoft To Do؟",
  "help.faq.a14":
    "نعم. تستخدم صفحة To-Do قوائمك في Microsoft To Do؛ والمهمة التي تضيفها أو تكملها هنا تظهر أيضًا في To Do داخل Outlook وTeams.",
  "help.faq.q15": "ماذا يعني تنبيه «انتهت صلاحية جلستك»؟",
  "help.faq.a15":
    "لأسباب أمنية تُجدَّد الجلسة على فترات. اضغط «سجّل الدخول مجددًا» في التنبيه، وغالبًا ستتابع من حيث توقفت دون كلمة مرور.",
  "help.faq.copyLink": "نسخ الرابط",
  "help.faq.copied": "تم نسخ الرابط",
