  "cause.why.popup": "أُغلقت نافذة Microsoft أو حُجبت: اسمح بالنوافذ المنبثقة وحاول مجددًا.",
  "cause.why.member":
    "لست مستخدمًا في بيئة {service} أو حسابك معطّل: على تقنية المعلومات إضافتك (ترخيص أو مجموعة أمان).",
  "cause.why.role":
    "دورك في {service} تنقصه صلاحية لهذا الإجراء: على تقنية المعلومات مراجعة الدور.",
  "cause.why.erpRole":
    "دورك في نظام ERP ‏(Dynamics 365 F&O) لا يسمح بقراءة هذه البيانات: على تقنية المعلومات منحك دورًا يقرؤها.",
  "cause.why.denied":
    "رفضت خدمة {service} الوصول{scopeNote}: قد لا يكون المورد مشاركًا معك أو ينقصك ترخيص أو لا يكفي الإذن.",
  "cause.why.busy": "خدمة {service} مشغولة جدًا الآن (حد الطلبات): حاول مجددًا بعد دقيقة.",
  "cause.why.timeout":
    "لم تردّ خدمة {service} في الوقت المناسب (انتهت المهلة): حاول مجددًا، وإن استمر ذلك فأرسل الرمز إلى تقنية المعلومات.",
  "cause.why.offline": "يبدو أن جهازك غير متصل: تحقق من الاتصال وحاول مجددًا.",
  "cause.why.network":
    "تعذّر الوصول إلى الخدمة ({service}): قد تكون الشبكة منقطعة أو يحجبها VPN أو جدار حماية أو الخدمة مشغولة.",
  "cause.why.server":
    "حدث خطأ من جهة {service} (HTTP {status}): غالبًا مؤقت؛ حاول بعد قليل وأرسل الرمز إلى تقنية المعلومات إن استمر.",
  "cause.why.noMailbox":
    "تعذّر الوصول إلى صندوق البريد: لا يوجد صندوق Exchange Online أو غير مفعّل أو موجود محليًا. على تقنية المعلومات التحقق.",
  "cause.why.notFound": "لم يُعثر على المورد ({service}): ربما حُذف أو نُقل أو غير متاح لك.",
  "cause.why.conflict": "تغيّر السجل في مكان آخر أو أنه موجود بالفعل (تعارض): حدّث وحاول مجددًا.",
  "cause.why.tooLarge": "البيانات المرسلة كبيرة جدًا: صغّر الملف وحاول مجددًا.",
  "cause.why.badQuery":
    "رفضت خدمة {service} الطلب (HTTP {status}): قد تكون هناك مشكلة في طلب TYRO؛ أرسل الرمز إلى تقنية المعلومات.",
  "cause.why.bigAccount":
    "حساب OneNote لديك كبير جدًا (أقسام أو عناصر كثيرة): لم تُرجِع {service} قائمة الصفحات. حاول بعد قليل، وإن استمر ذلك فأرسل الرمز إلى تقنية المعلومات.",
  "cause.why.drive":
    "تعذّر الوصول إلى OneDrive لديك ({service}): قد يكون قيد الإعداد أو هناك مشكلة في الترخيص أو الحصة. حاول بعد قليل، وإن استمر ذلك فأرسل الرمز إلى تقنية المعلومات.",
